import pytest

from seed.types.dial import Dial


def test_from_xml_to_xml_round_trips() -> None:
    parsed = Dial.from_xml(
        '<tw:Dial xmlns:tw="https://www.twilio.com/twiml" statusCallbackEvent="statusCallbackEvent statusCallbackEvent-2"><Numbers><Number /></Numbers></tw:Dial>'
    )
    assert parsed.status_callback_event == ["statusCallbackEvent", "statusCallbackEvent-2"]
    serialized = parsed.to_xml(xml_declaration=False)
    assert 'statusCallbackEvent="statusCallbackEvent statusCallbackEvent-2"' in serialized
    assert Dial.from_xml(serialized).to_xml(xml_declaration=False) == serialized
    assert parsed.to_xml().startswith('<?xml version="1.0"')
    assert str(parsed) == parsed.to_xml()


def test_from_xml_preserves_unknown_attributes_and_children() -> None:
    parsed = Dial.from_xml(
        '<tw:Dial xmlns:tw="https://www.twilio.com/twiml" dataUnknown="1"><Unknown a="1">v</Unknown></tw:Dial>'
    )
    serialized = parsed.to_xml(xml_declaration=False)
    assert 'dataUnknown="1"' in serialized
    assert '<Unknown a="1">v</Unknown>' in serialized
    assert Dial.from_xml(serialized).to_xml(xml_declaration=False) == serialized


def test_from_xml_rejects_wrong_root_element() -> None:
    with pytest.raises(ValueError):
        Dial.from_xml("<NotThetw:Dial />")


def test_from_xml_rejects_malformed_xml() -> None:
    with pytest.raises(ValueError):
        Dial.from_xml("<tw:Dial><unclosed>")


def test_from_xml_rejects_doctype() -> None:
    with pytest.raises(ValueError):
        Dial.from_xml(
            '<!DOCTYPE tw:Dial [<!ENTITY xxe "injected">]><tw:Dial xmlns:tw="https://www.twilio.com/twiml">&xxe;</tw:Dial>'
        )
